  `Week` int NOT NULL,
  `DayOfWeek` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `IsWeekend` tinyint(1) NOT NULL,
  PRIMARY KEY (`DateKey`),
  UNIQUE KEY `FullDate` (`FullDate`)
