DROP TABLE IF EXISTS `fact_forecast`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `fact_forecast` (
  `ForecastKey` bigint NOT NULL AUTO_INCREMENT,
  `ForecastType` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `PeriodLabel` date NOT NULL,
  `ProductKey` int DEFAULT NULL,
  `PredictedValue` decimal(18,2) NOT NULL,
  `ConfidenceLower` decimal(18,2) DEFAULT NULL,
  `ConfidenceUpper` decimal(18,2) DEFAULT NULL,
  `ModelName` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `GeneratedAt` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`ForecastKey`),
  KEY `fk_forecast_product` (`ProductKey`),
  KEY `idx_forecast_type` (`ForecastType`),
  KEY `idx_forecast_date` (`PeriodLabel`),
  KEY `idx_forecast_type_date` (`ForecastType`,`PeriodLabel`),
  CONSTRAINT `fk_forecast_product` FOREIGN KEY (`ProductKey`) REFERENCES `dim_product` (`ProductKey`)
) ENGINE=InnoDB AUTO_INCREMENT=127 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
