--
-- Table structure for table `fact_order_items`
--

DROP TABLE IF EXISTS `fact_order_items`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `fact_order_items` (
  `OrderItemKey` bigint NOT NULL AUTO_INCREMENT,
  `OrderKey` bigint NOT NULL,
  `ProductKey` int NOT NULL,
  `Quantity` int NOT NULL,
  `UnitPrice` decimal(12,2) NOT NULL,
  `DiscountAmount` decimal(12,2) NOT NULL DEFAULT '0.00',
  `SalesAmount` decimal(14,2) NOT NULL,
  `CostAmount` decimal(14,2) NOT NULL,
  `ProfitAmount` decimal(14,2) NOT NULL,
  PRIMARY KEY (`OrderItemKey`),
  KEY `idx_order_items_order` (`OrderKey`),
  KEY `idx_order_items_product` (`ProductKey`),
  CONSTRAINT `fk_order_items_order` FOREIGN KEY (`OrderKey`) REFERENCES `fact_orders` (`OrderKey`),
  CONSTRAINT `fk_order_items_product` FOREIGN KEY (`ProductKey`) REFERENCES `dim_product` (`ProductKey`),
  CONSTRAINT `chk_order_items_discount` CHECK ((`DiscountAmount` >= 0)),
  CONSTRAINT `chk_order_items_price` CHECK ((`UnitPrice` >= 0)),
  CONSTRAINT `chk_order_items_quantity` CHECK ((`Quantity` > 0))
) ENGINE=InnoDB AUTO_INCREMENT=16384 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

