--
-- Table structure for table `fact_orders`
--

DROP TABLE IF EXISTS `fact_orders`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `fact_orders` (
  `OrderKey` bigint NOT NULL AUTO_INCREMENT,
  `OrderID` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL,
  `CustomerKey` int NOT NULL,
  `DateKey` int NOT NULL,
  `ChannelKey` int NOT NULL,
  `LocationKey` int NOT NULL,
  `OrderStatus` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `PaymentStatus` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `ShippingStatus` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `OrderTotal` decimal(14,2) NOT NULL,
  `DiscountAmount` decimal(14,2) NOT NULL DEFAULT '0.00',
  `TaxAmount` decimal(14,2) NOT NULL DEFAULT '0.00',
  `ShippingAmount` decimal(14,2) NOT NULL DEFAULT '0.00',
  PRIMARY KEY (`OrderKey`),
  UNIQUE KEY `OrderID` (`OrderID`),
  KEY `idx_orders_customer` (`CustomerKey`),
  KEY `idx_orders_date` (`DateKey`),
  KEY `idx_orders_channel` (`ChannelKey`),
  KEY `idx_orders_location` (`LocationKey`),
  CONSTRAINT `fk_orders_channel` FOREIGN KEY (`ChannelKey`) REFERENCES `dim_channel` (`ChannelKey`),
  CONSTRAINT `fk_orders_customer` FOREIGN KEY (`CustomerKey`) REFERENCES `dim_customer` (`CustomerKey`),
  CONSTRAINT `fk_orders_date` FOREIGN KEY (`DateKey`) REFERENCES `dim_date` (`DateKey`),
  CONSTRAINT `fk_orders_location` FOREIGN KEY (`LocationKey`) REFERENCES `dim_location` (`LocationKey`),
  CONSTRAINT `chk_orders_discount` CHECK ((`DiscountAmount` >= 0)),
  CONSTRAINT `chk_orders_shipping` CHECK ((`ShippingAmount` >= 0)),
  CONSTRAINT `chk_orders_tax` CHECK ((`TaxAmount` >= 0)),
  CONSTRAINT `chk_orders_total` CHECK ((`OrderTotal` >= 0))
) ENGINE=InnoDB AUTO_INCREMENT=8192 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

