DROP TABLE IF EXISTS `fact_payments`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `fact_payments` (
  `PaymentKey` bigint NOT NULL AUTO_INCREMENT,
  `OrderKey` bigint NOT NULL,
  `DateKey` int NOT NULL,
  `PaymentMethod` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `PaymentAmount` decimal(14,2) NOT NULL,
  `PaymentStatus` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `TransactionFee` decimal(12,2) NOT NULL DEFAULT '0.00',
  PRIMARY KEY (`PaymentKey`),
  KEY `idx_payments_order` (`OrderKey`),
  KEY `idx_payments_date` (`DateKey`),
  CONSTRAINT `fk_payments_date` FOREIGN KEY (`DateKey`) REFERENCES `dim_date` (`DateKey`),
  CONSTRAINT `fk_payments_order` FOREIGN KEY (`OrderKey`) REFERENCES `fact_orders` (`OrderKey`),
  CONSTRAINT `chk_payment_amount` CHECK ((`PaymentAmount` >= 0)),
  CONSTRAINT `chk_transaction_fee` CHECK ((`TransactionFee` >= 0))
) ENGINE=InnoDB AUTO_INCREMENT=8192 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
