--
-- Table structure for table `fact_returns`
--

DROP TABLE IF EXISTS `fact_returns`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `fact_returns` (
  `ReturnKey` bigint NOT NULL AUTO_INCREMENT,
  `OrderKey` bigint NOT NULL,
  `CustomerKey` int NOT NULL,
  `ProductKey` int NOT NULL,
  `DateKey` int NOT NULL,
  `QuantityReturned` int NOT NULL,
  `RefundAmount` decimal(14,2) NOT NULL,
  `ReturnReason` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL,
  PRIMARY KEY (`ReturnKey`),
  KEY `idx_returns_order` (`OrderKey`),
  KEY `idx_returns_customer` (`CustomerKey`),
  KEY `idx_returns_product` (`ProductKey`),
  KEY `idx_returns_date` (`DateKey`),
  CONSTRAINT `fk_returns_customer` FOREIGN KEY (`CustomerKey`) REFERENCES `dim_customer` (`CustomerKey`),
  CONSTRAINT `fk_returns_date` FOREIGN KEY (`DateKey`) REFERENCES `dim_date` (`DateKey`),
  CONSTRAINT `fk_returns_order` FOREIGN KEY (`OrderKey`) REFERENCES `fact_orders` (`OrderKey`),
  CONSTRAINT `fk_returns_product` FOREIGN KEY (`ProductKey`) REFERENCES `dim_product` (`ProductKey`),
  CONSTRAINT `chk_refund_amount` CHECK ((`RefundAmount` >= 0)),
  CONSTRAINT `chk_return_quantity` CHECK ((`QuantityReturned` > 0))
) ENGINE=InnoDB AUTO_INCREMENT=528 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

