--
-- Table structure for table `fact_reviews`
--

DROP TABLE IF EXISTS `fact_reviews`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `fact_reviews` (
  `ReviewKey` bigint NOT NULL AUTO_INCREMENT,
  `CustomerKey` int NOT NULL,
  `ProductKey` int NOT NULL,
  `DateKey` int NOT NULL,
  `Rating` int NOT NULL,
  `ReviewSentiment` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `ReviewText` text COLLATE utf8mb4_unicode_ci,
  PRIMARY KEY (`ReviewKey`),
  KEY `idx_reviews_customer` (`CustomerKey`),
  KEY `idx_reviews_product` (`ProductKey`),
  KEY `idx_reviews_date` (`DateKey`),
  CONSTRAINT `fk_reviews_customer` FOREIGN KEY (`CustomerKey`) REFERENCES `dim_customer` (`CustomerKey`),
  CONSTRAINT `fk_reviews_date` FOREIGN KEY (`DateKey`) REFERENCES `dim_date` (`DateKey`),
  CONSTRAINT `fk_reviews_product` FOREIGN KEY (`ProductKey`) REFERENCES `dim_product` (`ProductKey`),
  CONSTRAINT `chk_review_rating` CHECK ((`Rating` between 1 and 5))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

