DROP TABLE IF EXISTS `fact_shipments`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `fact_shipments` (
  `ShipmentKey` bigint NOT NULL AUTO_INCREMENT,
  `OrderKey` bigint NOT NULL,
  `DateKey` int NOT NULL,
  `ShippingMethod` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `ShippingCost` decimal(12,2) NOT NULL,
  `ShipmentStatus` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `ShippedDate` date DEFAULT NULL,
  `DeliveredDate` date DEFAULT NULL,
  `DeliveryDays` int DEFAULT NULL,
  PRIMARY KEY (`ShipmentKey`),
  KEY `idx_shipments_order` (`OrderKey`),
  KEY `idx_shipments_date` (`DateKey`),
  CONSTRAINT `fk_shipments_date` FOREIGN KEY (`DateKey`) REFERENCES `dim_date` (`DateKey`),
  CONSTRAINT `fk_shipments_order` FOREIGN KEY (`OrderKey`) REFERENCES `fact_orders` (`OrderKey`),
  CONSTRAINT `chk_delivery_days` CHECK (((`DeliveryDays` is null) or (`DeliveryDays` >= 0))),
  CONSTRAINT `chk_shipping_cost` CHECK ((`ShippingCost` >= 0))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
