  `CustomerKey` int NOT NULL,
  `DateKey` int NOT NULL,
  `TicketID` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL,
  `IssueType` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `Priority` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL,
  `ResolutionTimeHours` decimal(10,2) DEFAULT NULL,
  `SatisfactionScore` decimal(5,2) DEFAULT NULL,
  `Status` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  PRIMARY KEY (`SupportKey`),
  UNIQUE KEY `TicketID` (`TicketID`),
  KEY `idx_support_customer` (`CustomerKey`),
  KEY `idx_support_date` (`DateKey`),
  CONSTRAINT `fk_support_customer` FOREIGN KEY (`CustomerKey`) REFERENCES `dim_customer` (`CustomerKey`),
  CONSTRAINT `fk_support_date` FOREIGN KEY (`DateKey`) REFERENCES `dim_date` (`DateKey`),
  CONSTRAINT `chk_resolution_time` CHECK (((`ResolutionTimeHours` is null) or (`ResolutionTimeHours` >= 0))),
  CONSTRAINT `chk_satisfaction` CHECK (((`SatisfactionScore` is null) or (`SatisfactionScore` between 0 and 5)))
) ENGINE=InnoDB AUTO_INCREMENT=1025 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
