  `Finding` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `Implication` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `RecommendationText` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `Priority` enum('Low','Medium','High') COLLATE utf8mb4_unicode_ci NOT NULL,
  `Status` enum('New','InProgress','Done','Dismissed') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'New',
  `AssignedToUserKey` int DEFAULT NULL,
  `CreatedAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `UpdatedAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `ResolvedAt` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`RecommendationKey`),
  KEY `fk_recommendations_assignee` (`AssignedToUserKey`),
  KEY `idx_recommendations_insight_status` (`InsightId`,`Status`),
  KEY `idx_recommendations_status` (`Status`),
  KEY `idx_recommendations_category` (`Category`),
  KEY `idx_recommendations_priority` (`Priority`),
  CONSTRAINT `fk_recommendations_assignee` FOREIGN KEY (`AssignedToUserKey`) REFERENCES `users` (`UserKey`)
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
